/** Presentation facts only. A recorded report is historical evidence, not a
 * promise that current generation/rotation conditions are still satisfied. */
export function deploymentFlightFacts(s:DeploymentRuntime,t:CommissioningTelemetry){
 const requirements=COMMISSIONING_REQUIREMENTS;
 return {powerNowMet:t.solarPowerW>=requirements.minimumSolarW,rotationNowMet:Math.abs(t.bodyRateRadS)<=requirements.maximumBodyRateRadS,
  reportRecorded:s.diagnosticCreatedAt!==null,failed:s.status==='failed',complete:s.status==='complete',pendingReceipt:hasDeploymentPendingDrain(s),safeMode:s.safeMode,
  powerW:t.solarPowerW,loadW:t.loadPowerW,bodyRateDegS:Math.abs(t.bodyRateRadS)*180/Math.PI,stableSeconds:s.solarGoodSeconds,receivedBits:s.diagnosticReceivedBits};
}

