 private preset(lesson:Lesson){return lesson==='clearance'?createDeploymentClearanceLesson():lesson==='recovery'?createDeploymentRecoveryLesson():{craft:createDeploymentCraft(lesson==='fixed'?'fixed':'folded'),plan:createDeploymentPlan(lesson==='fixed')};}
