   if(interruptedRestore){this.restoring=false;this.notice=word('불러오기를 정지하고 이전 상태를 유지했습니다.','Restore stopped; previous state retained.');if(!this.draft)this.evaluate();}
   if(m.type==='launched'){this.equipmentOpen=false;this.focusAfterPaint=null;this.playing=true;this.demand=this.live!.state.time;this.preview=null;this.previewReport=null;this.previewLabel='';this.selectedJoint=null;this.scene.selectJoint(null);this.timelineCollapsed=true;this.scene.setView('craft');this.lastAuto=0;}
   if(m.type==='restore-cancelled'){this.restoring=false;if(m.draft)this.adoptDraft(m.draft);this.notice=word('불러오기를 취소했습니다. 이전 상태를 유지합니다.','Restore cancelled. The previous state is retained.');}
